import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = '/tmp/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-secret-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'ak_admin_9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('service', 'svc@corp.internal', 'service', 'ak_svc_1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def verify_request_signature():
    # Internal integrity check - verify HMAC of request body for POST/PUT
    if request.method in ('POST', 'PUT'):
        sig = request.headers.get('X-Request-Signature')
        if sig:
            body = request.get_data()
            expected = hmac.new(SECRET_KEY.encode(), body, hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                return jsonify({'error': 'invalid signature'}), 403

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Log the search for audit
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES ('search', ?)",
               (f"field={field}, value={value}",))
    db.commit()

    # Build query with validated field name but user-supplied value
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'missing fields'}), 400
    db = get_db()
    try:
        db.execute("INSERT INTO users (username, email) VALUES (?, ?)",
                   (data['username'], data['email']))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
